JSON.stringify((function(){
    const cards=[...document.querySelectorAll('[data-im="card"]')].map(c=>{const r=c.getBoundingClientRect();return {attr:[...c.attributes].map(a=>a.name+'='+a.value).filter(x=>x.startsWith('data-')).join(','), cls:c.className, left:Math.round(r.left),top:Math.round(r.top),w:Math.round(r.width),h:Math.round(r.height)};});
    const surface=[...document.querySelectorAll('*')].filter(e=>/surface|board/i.test(e.className||'')&&e.children.length>3).slice(0,4).map(e=>({cls:e.className, left:Math.round(e.getBoundingClientRect().left), top:Math.round(e.getBoundingClientRect().top), w:Math.round(e.getBoundingClientRect().width), h:Math.round(e.getBoundingClientRect().height)}));
    const hooks=[...document.querySelectorAll('[data-im]')].map(e=>e.getAttribute('data-im'));
    return {cards, surface, hooks:[...new Set(hooks)].sort()};
  })())
